import type { Category } from '../types/flashcards';

export const APP_CATEGORIES: Category[] = [{"id":"flashcards_AWS_API_Gateway","file":"flashcards_AWS_API_Gateway.html","title":"Flashcards: Amazon API Gateway","subtitle":"Clique em um cartão para virá-lo e revelar a definição técnica.","cardCount":6,"cards":[{"front":"Amazon API Gateway","back":"Um serviço totalmente gerenciado da AWS que facilita a criação, publicação, manutenção, monitoramento e proteção de APIs em qualquer escala."},{"front":"Benefícios Principais","back":"Escalabilidade automática para gerenciar tráfego, proteção contra picos, mecanismos flexíveis de autorização de acesso e gerenciamento do ciclo de vida da API."},{"front":"Arquitetura de Front Door","back":"Atua como uma \"porta de entrada\" centralizada para que aplicativos acessem dados e lógicas de negócios executadas em backends como AWS Lambda ou instâncias EC2."},{"front":"Endpoints Otimizados para a Borda","back":"Tipo de endpoint de API roteado pela rede global do Amazon CloudFront, ideal para reduzir a latência de clientes distribuídos geograficamente."},{"front":"Endpoints Regionais e Privados","back":"Endpoints Regionais atendem clientes na mesma região da API. Endpoints Privados são isolados e acessíveis apenas de dentro de uma Amazon VPC."},{"front":"Throttling (Limitação de Taxa)","back":"Mecanismo de proteção que previne a sobrecarga dos serviços de backend, limitando a quantidade de requisições por segundo que a API processará de um cliente."}],"domain":"Redes & Entrega de Conteúdo","domainIcon":"🌐","index":0},{"id":"flashcards_AWS_APIs_REST","file":"flashcards_AWS_APIs_REST.html","title":"Conceitos de APIs e REST","subtitle":"Conceitos de APIs e REST Clique nos cartões para revelar as definições técnicas","cardCount":6,"cards":[{"front":"<h2>API (Interface de Programação de Aplicativo)</h2>","back":"<p>Fornece acesso programático às funções de uma aplicação de maneira consistente, permitindo que diferentes programas de software se comuniquem entre si.</p>"},{"front":"<h2>REST</h2>","back":"<p>Significa Transferência de Estado Representacional. É um estilo de arquitetura para projetar aplicativos em rede e fornece diretrizes para a criação de APIs web.</p>"},{"front":"<h2>Aplicação Cliente</h2>","back":"<p>O software ou sistema que inicia a comunicação, enviando uma solicitação à aplicação do servidor usando a API correspondente.</p>"},{"front":"<h2>Aplicação do Servidor</h2>","back":"<p>O sistema que recebe a solicitação da aplicação cliente através da API, processa as informações e retorna uma resposta.</p>"},{"front":"<h2>Chamada de API</h2>","back":"<p>Uma mensagem entregue a uma aplicação na forma de solicitação, que depois é processada e retornada como uma resposta ao solicitante original.</p>"},{"front":"<h2>GUI (Interface Gráfica do Usuário)</h2>","back":"<p>Uma interface visual usada por pessoas para interagir com aplicações. APIs são benéficas porque permitem acessar as funções do sistema sem a necessidade de usar uma GUI.</p>"}],"domain":"Gerenciamento, SysOps & Automação","domainIcon":"🛠️","index":1},{"id":"flashcards_AWS_Aurora","file":"flashcards_AWS_Aurora.html","title":"Flashcards de Revisão: Amazon Aurora","subtitle":"","cardCount":6,"cards":[{"front":"O que é o Amazon Aurora?\n                    <span class=\"hint\">Clique para virar</span>","back":"É um mecanismo de banco de dados relacional totalmente gerenciado compatível com o MySQL e o PostgreSQL."},{"front":"Qual é a principal proposta de valor do Aurora?\n                    <span class=\"hint\">Clique para virar</span>","back":"Combina o desempenho e a disponibilidade dos bancos de dados comerciais de alta tecnologia com a simplicidade e a economia dos bancos de código aberto."},{"front":"De qual serviço gerenciado o Aurora faz parte?\n                    <span class=\"hint\">Clique para virar</span>","back":"Ele faz parte do serviço de banco de dados gerenciado Amazon Relational Database Service (Amazon RDS)."},{"front":"Como o desempenho do Aurora se compara ao MySQL padrão?\n                    <span class=\"hint\">Clique para virar</span>","back":"O Aurora é até cinco vezes mais rápido que os bancos de dados MySQL padrão."},{"front":"Qual é a estrutura de composição do Aurora?\n                    <span class=\"hint\">Clique para virar</span>","back":"O Aurora é composto por clusters."},{"front":"Quais tarefas complexas de administração o Aurora automatiza e padroniza?\n                    <span class=\"hint\">Clique para virar</span>","back":"Ele automatiza e padroniza o agrupamento de clusters e a replicação de bancos de dados."}],"domain":"Armazenamento & Banco de Dados","domainIcon":"💾","index":2},{"id":"flashcards_AWS_Auto_Scaling","file":"flashcards_AWS_Auto_Scaling.html","title":"Conceitos de Scaling AWS","subtitle":"Clique em qualquer cartão para ver a definição técnica.","cardCount":7,"cards":[{"front":"Scaling","back":"É a capacidade de aumentar ou diminuir a capacidade computacional para atender à flutuação na demanda."},{"front":"Aumento de Escala Horizontal","back":"Ação de adicionar mais recursos ou instâncias quando a demanda ou tráfego aumenta."},{"front":"Redução de Escala Horizontal","back":"Ação de remover recursos ou instâncias quando a capacidade necessária diminui."},{"front":"Amazon EC2 Auto Scaling","back":"Serviço que ajuda a garantir o número correto de instâncias disponíveis, respeitando limites máximo, mínimo ou de capacidade pré-definidos."},{"front":"Tolerância a Falhas no Auto Scaling","back":"Capacidade de detectar instâncias não íntegras, encerrá-las e substituí-las, podendo até iniciar instâncias em outras Zonas de Disponibilidade."},{"front":"Otimização de Custos","back":"Benefício de aumentar ou diminuir a capacidade dinamicamente, permitindo pagar apenas pelas instâncias quando elas são realmente necessárias."},{"front":"Alta Disponibilidade e Desempenho","back":"Garante a capacidade adequada para o tráfego atual, distribuindo e compartilhando o trabalho para manter um bom tempo de resposta."}],"domain":"Computação & Contêineres","domainIcon":"💻","index":3},{"id": "flashcards_AWS_CAF-WAF", "file": "flashcards_AWS_CAF-WAF.html", "title": "Flashcards de Revisão: AWS CAF & Well-Architected", "subtitle": "Clique nos cartões para virar e conferir as respostas técnicas.", "cardCount": 12, "cards": [{"front": "<div class=\"tag\">Pergunta</div><p>O que é o AWS CAF?</p>", "back": "<div class=\"tag\">Resposta</div><p>Um guia estratégico para ajudar a <strong>empresa inteira</strong> a planejar e executar a migração para a nuvem de forma estruturada.</p>"}, {"front": "<div class=\"tag\">Analogia</div><p>Qual é a analogia do CAF?</p>", "back": "<div class=\"tag\">Resposta</div><p>A \"Planta Baixa\" da casa. Pensa em quem vai morar, como pagar e as regras de convivência.</p>"}, {"front": "<div class=\"tag\">Conceito</div><p>O CAF é apenas para a TI?</p>", "back": "<div class=\"tag\">Resposta</div><p>Não. Ele divide a transformação em tecnologia, processos e pessoas.</p>"}, {"front": "<div class=\"tag\">Listagem</div><p>Quais são as 6 Perspectivas do CAF?</p>", "back": "<div class=\"tag\">Resposta</div><p>1. Negócios<br>2. Pessoas<br>3. Governança<br>4. Plataforma<br>5. Segurança<br>6. Operações</p>"}, {"front": "<div class=\"tag\">Pergunta</div><p>O que é o Well-Architected?</p>", "back": "<div class=\"tag\">Resposta</div><p>Um checklist técnico para avaliar se os <strong>sistemas e aplicações</strong> foram construídos com as melhores práticas.</p>"}, {"front": "<div class=\"tag\">Analogia</div><p>Qual é a analogia do Well-Architected?</p>", "back": "<div class=\"tag\">Resposta</div><p>A \"Vistoria do Engenheiro\". Avalia se a casa (arquitetura) é segura, não desperdiça energia e aguenta tempestades.</p>"}, {"front": "<div class=\"tag\">Listagem</div><p>Quais são os 6 Pilares?</p>", "back": "<div class=\"tag\">Resposta</div><p>1. Excel. Operacional<br>2. Segurança<br>3. Confiabilidade<br>4. Desempenho<br>5. Custos<br>6. Sustentabilidade</p>"}, {"front": "<div class=\"tag\">Pergunta</div><p>Qual pilar evita pagar por recursos parados?</p>", "back": "<div class=\"tag\">Resposta</div><p>O pilar de <strong>Otimização de Custos</strong>.</p>"}, {"front": "<div class=\"tag\">Cenário</div><p>\"A equipe do RH não sabe como treinar os funcionários para usar a nuvem.\"</p>", "back": "<div class=\"tag\">Solução</div><p><strong>CAF</strong><br>(Perspectiva de Pessoas)</p>"}, {"front": "<div class=\"tag\">Cenário</div><p>\"Nosso e-commerce ficou lento durante a Black Friday.\"</p>", "back": "<div class=\"tag\">Solução</div><p><strong>Well-Architected</strong><br>(Desempenho / Confiabilidade)</p>"}, {"front": "<div class=\"tag\">Cenário</div><p>\"A diretoria quer garantir que o investimento aumente a receita em 15%.\"</p>", "back": "<div class=\"tag\">Solução</div><p><strong>CAF</strong><br>(Perspectiva de Negócios)</p>"}, {"front": "<div class=\"tag\">Cenário</div><p>\"O banco de dados foi invadido porque uma porta ficou aberta.\"</p>", "back": "<div class=\"tag\">Solução</div><p><strong>Well-Architected</strong><br>(Pilar de Segurança)</p>"}], "domain": "Frameworks & Melhores Práticas", "domainIcon": "📐", "index": 4},{"id":"flashcards_AWS_CAF","file":"flashcards_AWS_CAF.html","title":"Flashcards: AWS CAF","subtitle":"Clique nos cartões para revelar as definições","cardCount":6,"cards":[{"front":"AWS Cloud Adoption Framework (CAF)\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Estrutura que orienta as organizações na criação de um plano abrangente e eficiente de migração e transformação para a nuvem, alinhando negócios e tecnologia."},{"front":"Perspectiva de Negócios (Business)\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Foca em garantir que os investimentos em nuvem acelerem a transformação digital e alcancem os resultados e metas de negócios desejados."},{"front":"Perspectiva de Pessoas (People)\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Serve de ponte entre a tecnologia e os negócios, ajudando as organizações a treinar equipes, desenvolver lideranças e gerenciar mudanças culturais."},{"front":"Perspectiva de Governança (Governance)\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Ajuda a gerenciar e medir iniciativas em nuvem para maximizar o valor dos negócios e minimizar os riscos corporativos e financeiros."},{"front":"Perspectiva de Segurança (Security)\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Estrutura o controle e o gerenciamento para alcançar a confidencialidade, a integridade e a disponibilidade de dados e cargas de trabalho na AWS."},{"front":"Perspectiva de Operações (Operations)\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Foca em como os serviços de TI são operados, entregues e recuperados na nuvem para atender aos níveis de serviço acordados com as partes interessadas."}],"domain":"Frameworks & Melhores Práticas","domainIcon":"📐","index":5},{"id":"flashcards_AWS_CLI","file":"flashcards_AWS_CLI.html","title":"Módulo: AWS Command Line Interface","subtitle":"Clique para ver a definição","cardCount":6,"cards":[{"front":"AWS Command Line Interface (AWS CLI)","back":"Uma ferramenta unificada, de código aberto, que permite interagir com os serviços da AWS usando comandos no shell de linha de comando."},{"front":"Instalação no Linux","back":"As etapas comuns envolvem baixar o arquivo de instalação (.zip), descompactá-lo e executar o script de instalação do pacote fornecido pela AWS."},{"front":"Detalhes e Funcionalidades","back":"A AWS CLI permite criar scripts de automação, gerenciar recursos em lote e controlar múltiplos serviços diretamente pelo terminal, sem usar o console web."},{"front":"aws configure","back":"O comando principal para configurar a AWS CLI. Ele solicita a Access Key, Secret Access Key, região padrão e formato de saída."},{"front":"Região Padrão (Default Region)","back":"O data center geográfico (como us-east-1 ou sa-east-1) para o qual a AWS CLI enviará as solicitações de API, a menos que especificado de outra forma no comando."},{"front":"Formatos de Saída (Output)","back":"Define como os resultados da CLI são exibidos na tela. Os formatos mais comuns suportados são JSON (padrão), texto (text) e tabela (table)."}],"domain":"Gerenciamento, SysOps & Automação","domainIcon":"🛠️","index":6},{"id":"flashcards_AWS_CloudFront","file":"flashcards_AWS_CloudFront.html","title":"Conceitos: Amazon CloudFront","subtitle":"Clique em um cartão para ver a definição.","cardCount":6,"cards":[{"front":"Amazon CloudFront","back":"Serviço da AWS que atua como uma Rede de Entrega de Conteúdo (CDN), distribuindo dados de forma segura e com baixa latência."},{"front":"CDN (Content Delivery Network)","back":"Rede de servidores distribuídos globalmente focada em entregar conteúdo (vídeos, imagens, páginas web) aos usuários com maior rapidez."},{"front":"Edge Location","back":"Pontos de presença global (servidores de cache) da AWS que armazenam cópias de conteúdo para entregá-lo o mais perto possível do usuário final."},{"front":"Origin (Origem)","back":"O local principal de onde o CloudFront busca a versão original do seu conteúdo caso ele não esteja no cache (ex: um bucket do Amazon S3 ou um servidor EC2)."},{"front":"Cache Hit","back":"Ocorre quando o conteúdo solicitado pelo usuário já está armazenado no Edge Location mais próximo, resultando em uma entrega imediata."},{"front":"Distribution (Distribuição)","back":"A configuração principal criada no CloudFront que diz ao serviço de qual Origem buscar os arquivos e como gerenciar e rastrear a entrega desse conteúdo."}],"domain":"Redes & Entrega de Conteúdo","domainIcon":"🌐","index":7},{"id":"flashcards_AWS_Cloud_Trail","file":"flashcards_AWS_Cloud_Trail.html","title":"Revisão: AWS CloudTrail","subtitle":"Clique no cartão para virar","cardCount":6,"cards":[{"front":"O que é o AWS CloudTrail?","back":"É um serviço da web que registra chamadas da interface de programação de aplicativo (API) da AWS para sua conta e entrega arquivos de log para você."},{"front":"Principais benefícios do CloudTrail","back":"É uma ferramenta crucial para simplificar a governança, a conformidade e a auditoria de riscos em uma conta AWS."},{"front":"Escopo de monitoramento das APIs","back":"Tudo na AWS é uma chamada de API. O CloudTrail registra as ações feitas via AWS CLI, SDK, console ou diretamente por meio de uma API."},{"front":"Alcance geográfico do registro","back":"O CloudTrail registra as chamadas de API feitas em uma conta da AWS abrangendo todas as regiões AWS (entre as regiões)."},{"front":"Exemplos de ações registradas","back":"Iniciar/interromper instâncias do Amazon EC2, criar/modificar bancos de dados do Amazon RDS e fazer upload de arquivos para o Amazon S3."},{"front":"Valor operacional e de segurança","back":"O registro acelera a análise de problemas operacionais e de segurança ao disponibilizar total visibilidade sobre as ações realizadas na conta."}],"domain":"Gerenciamento, SysOps & Automação","domainIcon":"🛠️","index":8},{"id":"flashcards_AWS_Confiabilidade_Alta-Disponibilidade","file":"flashcards_AWS_Confiabilidade_Alta-Disponibilidade.html","title":"Revisão: Arquitetura e Resiliência","subtitle":"","cardCount":6,"cards":[{"front":"Confiabilidade (Reliability)","back":"A capacidade de um sistema se recuperar de interrupções e mitigar falhas, garantindo que a carga de trabalho execute sua função pretendida de forma consistente."},{"front":"Alta Disponibilidade (High Availability)","back":"O tempo em que uma aplicação permanece acessível e operando normalmente, minimizando o tempo de inatividade (downtime) sem intervenção humana."},{"front":"Fatores de Alta Disponibilidade","back":"Elementos arquitetônicos essenciais, como implantação em Múltiplas Zonas de Disponibilidade (Multi-AZ), balanceamento de carga e Auto Scaling."},{"front":"Tolerância a Falhas","back":"A capacidade de um sistema permanecer totalmente operacional mesmo que um ou mais de seus componentes sofram uma falha, geralmente suportada por redundância."},{"front":"Redundância","back":"A duplicação intencional de componentes críticos (como servidores ou bancos de dados) para garantir que, se um falhar, outro assuma imediatamente."},{"front":"Ponto Único de Falha (SPOF)","back":"Um componente em um sistema de TI que, caso pare de funcionar, fará com que todo o sistema fique indisponível. Arquiteturas confiáveis evitam SPOFs."}],"domain":"Frameworks & Melhores Práticas","domainIcon":"📐","index":9},{"id":"flashcards_AWS_Config","file":"flashcards_AWS_Config.html","title":"Flashcards - AWS Config","subtitle":"Clique em um cartão para revelar sua definição.","cardCount":6,"cards":[{"front":"<h2>AWS Config</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Serviço que avalia automaticamente, registra e normaliza as alterações de configuração dos recursos da AWS em relação às configurações desejadas.</p>"},{"front":"<h2>Normalização</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>O processo pelo qual o mecanismo do AWS Config registra e padroniza as alterações de recursos em um formato consistente.</p>"},{"front":"<h2>Armazenamento (Amazon S3)</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Destino para onde o registro de alterações normalizadas é entregue, permitindo que seja acessado por meio das APIs do Config.</p>"},{"front":"<h2>Avaliação de Regras</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Processo que verifica se a alteração em um recurso afetado não viola as diretrizes e regras de configuração definidas previamente.</p>"},{"front":"<h2>Notificações (Amazon SNS)</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Serviço de mensageria usado opcionalmente pelo AWS Config para enviar avisos sobre alterações ocorridas ou resultados das avaliações das regras.</p>"},{"front":"<h2>Desafio de Gerenciamento</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>A necessidade de ter visibilidade sobre erros humanos, rastrear o histórico e relatar o status atual em um ambiente com centenas ou milhares de recursos (ex: instâncias EC2).</p>"}],"domain":"Gerenciamento, SysOps & Automação","domainIcon":"🛠️","index":10},{"id":"flashcards_AWS_Conformidade_Seguranca","file":"flashcards_AWS_Conformidade_Seguranca.html","title":"Módulo de Conformidade de Segurança da AWS","subtitle":"","cardCount":6,"cards":[{"front":"Programa de Conformidade de Segurança da AWS","back":"Conjunto de controles e processos da AWS projetado para ajudar os clientes a manter a segurança, a proteção de dados na nuvem e atender a requisitos regulatórios."},{"front":"Programas de Garantia da AWS","back":"Certificações, atestados e estruturas globais e regionais (como SOC, PCI-DSS e ISO) que validam as práticas e a abordagem de conformidade da AWS."},{"front":"Gerenciamento de Riscos","back":"Um dos principais componentes do programa da AWS, focado em identificar, avaliar e mitigar riscos em toda a infraestrutura e nos serviços oferecidos em nuvem."},{"front":"Ambiente de Controle","back":"A estrutura de políticas, procedimentos e práticas implementadas pela AWS para garantir que os mecanismos de segurança e conformidade operem de maneira eficaz."},{"front":"Segurança da Informação","back":"As ferramentas e práticas operacionais empregadas para proteger ativamente a confidencialidade, a integridade e a disponibilidade dos sistemas e dados armazenados."},{"front":"Responsabilidades de Conformidade do Cliente","back":"A parte do modelo de responsabilidade compartilhada onde o cliente é encarregado de garantir a conformidade das configurações, dados e aplicativos que hospeda na AWS."}],"domain":"Segurança, IAM & Governança","domainIcon":"🔒","index":11},{"id":"flashcards_AWS_Conteiners","file":"flashcards_AWS_Conteiners.html","title":"Contêineres na AWS","subtitle":"Clique em um cartão para virá-lo e ver a definição.","cardCount":6,"cards":[{"front":"Contêineres","back":"Pacotes de software padronizados que agrupam o código de uma aplicação e todas as suas dependências, permitindo que o aplicativo seja executado de forma rápida e confiável em qualquer ambiente."},{"front":"Benefícios dos Contêineres","back":"Oferecem alta portabilidade, consistência entre ambientes de desenvolvimento e produção, eficiência de recursos (pois compartilham o kernel do sistema operacional) e rápida inicialização."},{"front":"Docker","back":"Uma plataforma de software livre popular e um padrão do setor usado para criar, implantar e gerenciar aplicações em contêineres de forma simplificada e escalável."},{"front":"Benefícios do Docker","back":"Acelera o ciclo de desenvolvimento, simplifica atualizações e implantações (CI/CD), garante que o software funcione de maneira idêntica em qualquer infraestrutura e melhora o isolamento de processos."},{"front":"Componentes do Docker","back":"Incluem o Docker Engine (serviço principal que roda os contêineres), Imagens Docker (modelos para criação), Dockerfile (script de configuração) e Docker Registry (repositórios de armazenamento como o Docker Hub)."},{"front":"Serviços de Contêineres AWS","back":"Serviços da nuvem Amazon voltados para orquestração e execução, destacando-se o Amazon ECS (Elastic Container Service), Amazon EKS (Elastic Kubernetes Service) e o AWS Fargate (computação sem servidor para contêineres)."}],"domain":"Computação & Contêineres","domainIcon":"💻","index":12},{"id":"flashcards_AWS_Data_Warehouse","file":"flashcards_AWS_Data_Warehouse.html","title":"Flashcards: Data Warehouse & AWS","subtitle":"Conceitos integrados sobre Arquitetura de Dados. Clique nos cartões para revelar as definições.","cardCount":6,"cards":[{"front":"O que é um Data Warehouse?\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Repositório central de dados limpos, estruturados e relacionais, otimizado para Business Intelligence (BI) e análises históricas."},{"front":"Arquitetura do Data Warehouse\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Dividida em 3 camadas:<br><br>\n                    1. Nível inferior (Servidor do Banco de dados)<br>\n                    2. Nível intermediário (Mecanismo de análises)<br>\n                    3. Nível superior (Cliente de front-end para relatórios)"},{"front":"O que é um Data Lake?\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Repositório centralizado para armazenar todos os dados estruturados e não estruturados em sua forma bruta e em qualquer escala, sem necessidade de estruturá-los previamente."},{"front":"Diferença entre Data Warehouse e Data Lakehouse\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"O Lakehouse combina o baixo custo de armazenamento e flexibilidade do Data Lake com as transações ACID e governança robusta do Data Warehouse."},{"front":"Amazon Redshift\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Um serviço de data warehouse na nuvem da AWS, totalmente gerenciado e projetado para operar na escala de petabytes."},{"front":"Fluxo de Uso do Data Warehouse\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"1. Carga no banco/Data Lake<br>\n                    2. Exploração e preparo dos dados<br>\n                    3. Movimentação dos dados selecionados para o Data Warehouse<br>\n                    4. Execução de relatórios"}],"domain":"Armazenamento & Banco de Dados","domainIcon":"💾","index":13},{"id":"flashcards_AWS_Docs","file":"flashcards_AWS_Docs.html","title":"Conceitos da AWS","subtitle":"","cardCount":6,"cards":[{"front":"Documentação da AWS","back":"Oferece informações abrangentes e detalhadas sobre cada serviço da AWS, incluindo manuais, referências de API e tutoriais organizados por categoria."},{"front":"Whitepapers da AWS","back":"Documentos técnicos recomendados para certificação, incluindo a \"Visão geral da Amazon Web Services\" e \"Melhores práticas da AWS para arquitetura para a nuvem\"."},{"front":"Recursos Gerais da AWS","back":"Incluem estudos de caso, um glossário de A a Z de termos da AWS, perguntas frequentes (FAQs) e informações sobre Treinamento e Certificação."},{"front":"SDKs e Toolkits","back":"Conjuntos de ferramentas que possuem documentação própria, como a AWS Command Line Interface (AWS CLI) e o AWS SDK for Python (Boto)."},{"front":"Documentação do Amazon EC2","back":"Inclui manuais do usuário para Linux e Windows, referências de API, referência da AWS CLI e o manual do Auto Scaling."},{"front":"Organização da Documentação","back":"Os artigos e manuais técnicos podem ser filtrados por produto, categoria ou setor, facilitando a busca pela informação mais relevante para as necessidades do usuário."}],"domain":"Frameworks & Melhores Práticas","domainIcon":"📐","index":14},{"id":"flashcards_AWS_DynamoDB","file":"flashcards_AWS_DynamoDB.html","title":"Conceitos: Amazon DynamoDB","subtitle":"Clique nos cartões para revelar as definições.","cardCount":6,"cards":[{"front":"Amazon DynamoDB","back":"Um serviço de banco de dados gerenciado pela Amazon Web Services, foco de estudo para a criação de soluções."},{"front":"Banco de Dados Relacional","back":"Modelo tradicional de banco de dados, frequentemente contrastado com o DynamoDB para destacar diferenças de arquitetura."},{"front":"Banco de Dados Não Relacional","back":"Categoria de banco de dados (como o próprio DynamoDB) desenhada para maior flexibilidade e escalabilidade em comparação aos relacionais."},{"front":"Partição","back":"Um dos principais termos técnicos do DynamoDB, utilizado para dividir e gerenciar os dados fisicamente no banco."},{"front":"Disponibilidade da Solução","back":"Característica que pode ser diretamente afetada pelas diversas opções e recursos escolhidos durante a configuração do serviço."},{"front":"Recursos do Serviço","back":"Diferentes capacidades e opções integradas ao banco de dados que servem para impulsionar e otimizar a sua solução na nuvem."}],"domain":"Armazenamento & Banco de Dados","domainIcon":"💾","index":15},{"id":"flashcards_AWS_EC2","file":"flashcards_AWS_EC2.html","title":"Conceitos de Computação AWS","subtitle":"Clique em um cartão para ver a definição.","cardCount":6,"cards":[{"front":"Amazon Elastic Compute Cloud (Amazon EC2)","back":"Serviço da AWS que oferece servidores virtuais seguros e redimensionáveis na nuvem."},{"front":"Amazon Lightsail","back":"Oferece servidores privados virtuais para a execução de cargas de trabalho simples de forma econômica."},{"front":"Amazon Elastic Container Service (Amazon ECS)","back":"Serviço que permite executar aplicativos de contêiner do Docker diretamente na AWS."},{"front":"AWS Elastic Beanstalk","back":"Solução (PaaS) que executa aplicativos web e serviços desenvolvidos em linguagens como Java, .NET, PHP, Node.js, Python, Ruby e Go."},{"front":"Máquinas Virtuais (VMs)","back":"Categoria de modelo de computação em nuvem que oferece o maior controle e personalização da infraestrutura."},{"front":"Plataforma como Serviço (PaaS)","back":"Modelo de serviços totalmente gerenciados que proporciona a implantação mais rápida de aplicativos sem precisar gerenciar a infraestrutura subjacente."}],"domain":"Computação & Contêineres","domainIcon":"💻","index":16},{"id":"flashcards_AWS_EC2_Auto_Scaling","file":"flashcards_AWS_EC2_Auto_Scaling.html","title":"Flashcards de Auto Scaling","subtitle":"(Clique para virar)","cardCount":6,"cards":[{"front":"<h2>Formas de definição de Auto Scaling</h2>\n                    <p class=\"hint\">(Clique para virar)</p>","back":"<p>O auto scaling pode ser definido de três maneiras principais: Alarmes do Amazon CloudWatch, Política com monitoramento de objetivo, e Ações programadas.</p>"},{"front":"<h2>Scaling baseado em Alarmes do CloudWatch</h2>\n                    <p class=\"hint\">(Clique para virar)</p>","back":"<p>Aumenta ou reduz a escala horizontalmente com base em um alarme específico, como a utilização média da CPU ser maior que 50% por 2 minutos.</p>"},{"front":"<h2>Scaling Simples</h2>\n                    <p class=\"hint\">(Clique para virar)</p>","back":"<p>Uma política de scaling acionada por alarme que serve para adicionar ou remover um <strong>número fixo</strong> de instâncias.</p>"},{"front":"<h2>Scaling em Etapas</h2>\n                    <p class=\"hint\">(Clique para virar)</p>","back":"<p>Ajusta o número de instâncias como uma <strong>porcentagem</strong> da capacidade desejada. A resposta varia de acordo com o tamanho da violação do alarme.</p>"},{"front":"<h2>Política com Monitoramento de Objetivo</h2>\n                    <p class=\"hint\">(Clique para virar)</p>","back":"<p>Avalia uma métrica em relação a uma meta constante. Por exemplo: manter a utilização média da CPU do grupo de Auto Scaling cravada em 50%.</p>"},{"front":"<h2>Ações Programadas (Scheduled Scaling)</h2>\n                    <p class=\"hint\">(Clique para virar)</p>","back":"<p>Define um novo valor de capacidade desejado em um horário ou data específica (ou de forma recorrente). Excelente para pré-aquecer a capacidade para picos de tráfego previsíveis.</p>"}],"domain":"Computação & Contêineres","domainIcon":"💻","index":17},{"id":"flashcards_AWS_ELB","file":"flashcards_AWS_ELB.html","title":"Flashcards: Balanceadores de Carga do ELB","subtitle":"(Clique para virar)","cardCount":6,"cards":[{"front":"Elastic Load Balancing (ELB)","back":"Serviço da AWS que distribui automaticamente o tráfego de entrada de aplicações entre vários destinos, garantindo escalabilidade e disponibilidade."},{"front":"Balanceador de Carga","back":"Recurso central que atua como um ponto único de contato para os clientes, distribuindo o tráfego de entrada entre os destinos registrados."},{"front":"Listener (Ouvinte)","back":"Um processo que verifica solicitações de conexão usando um protocolo e porta configurados, roteando o tráfego para os grupos de destino."},{"front":"Grupo de Destino (Target Group)","back":"Um agrupamento lógico de destinos, como instâncias do EC2, para os quais o balanceador de carga roteia solicitações."},{"front":"AWS Command Line Interface (AWS CLI)","back":"Ferramenta unificada para gerenciar serviços da AWS via linha de comando, permitindo a criação e configuração de balanceadores de carga via scripts."},{"front":"Componentes da Arquitetura ELB","back":"A estrutura básica envolve a integração do Balanceador de Carga (ponto de entrada), Ouvintes (regras de conexão) e Grupos de Destino (recursos que processam as requisições)."}],"domain":"Redes & Entrega de Conteúdo","domainIcon":"🌐","index":18},{"id":"flashcards_AWS_Elastic_Beanstalk","file":"flashcards_AWS_Elastic_Beanstalk.html","title":"Flashcards: AWS Elastic Beanstalk","subtitle":"","cardCount":6,"cards":[{"front":"AWS Elastic Beanstalk","back":"Serviço gerenciado que facilita a implantação e o dimensionamento de aplicações e serviços web sem a necessidade de provisionar ou gerenciar a infraestrutura subjacente."},{"front":"PaaS (Platform as a Service)","back":"Modelo de computação em nuvem do qual o Elastic Beanstalk faz parte. Foca em fornecer uma plataforma pronta para desenvolvedores criarem e rodarem aplicações."},{"front":"Ambiente (Environment)","back":"Uma versão provisionada da sua aplicação em execução. Consiste nos recursos da AWS (EC2, balanceadores de carga, etc.) configurados para executar seu código."},{"front":"Versão da Aplicação (Application Version)","back":"Uma iteração específica, rotulada e empacotada do código implantável de uma aplicação web armazenada no Elastic Beanstalk."},{"front":"Balanceador de Carga (Load Balancer)","back":"Recurso configurado automaticamente que distribui o tráfego de entrada da aplicação entre várias instâncias EC2, garantindo estabilidade e alta disponibilidade."},{"front":"Auto Scaling","back":"Recurso integrado que ajusta automaticamente o número de instâncias de computação ativas no ambiente com base na demanda de tráfego atual da aplicação."}],"domain":"Computação & Contêineres","domainIcon":"💻","index":19},{"id":"flashcards_AWS_Ferramentas_Adm","file":"flashcards_AWS_Ferramentas_Adm.html","title":"Flashcards: Ferramentas de Administração & Automação","subtitle":"","cardCount":6,"cards":[{"front":"Automação Administrativa","back":"Uso de tecnologia e ferramentas para executar tarefas operacionais e gerenciar infraestrutura com o mínimo de intervenção manual humana."},{"front":"AWS Systems Manager","back":"Ferramenta de administração que fornece visibilidade e controle sobre a infraestrutura da AWS, permitindo automatizar tarefas operacionais rotineiras."},{"front":"AWS CloudFormation","back":"Serviço de Infraestrutura como Código (IaC) que permite modelar, provisionar e gerenciar recursos de TI de forma automatizada e previsível."},{"front":"Infraestrutura como Código (IaC)","back":"O processo de gerenciar e provisionar data centers computacionais por meio de arquivos de definição legíveis por máquina, em vez de configuração de hardware interativa."},{"front":"AWS OpsWorks","back":"Serviço de gerenciamento de configuração que automatiza a configuração, a implantação e o gerenciamento de servidores usando o Chef ou o Puppet."},{"front":"AWS Config","back":"Ferramenta de administração que permite avaliar, auditar e monitorar continuamente as configurações dos recursos da sua conta AWS."}],"domain":"Gerenciamento, SysOps & Automação","domainIcon":"🛠️","index":20},{"id":"flashcards_AWS_IAM-2","file":"flashcards_AWS_IAM-2.html","title":"Conceitos do AWS IAM","subtitle":"","cardCount":6,"cards":[{"front":"<h2>AWS IAM</h2>\n                    <span class=\"instruction\">Clique para virar</span>","back":"<p><strong>Identity and Access Management:</strong> Um serviço web que permite controlar de forma segura o acesso aos recursos e serviços da AWS para seus usuários.</p>"},{"front":"<h2>Credenciais de Segurança</h2>\n                    <span class=\"instruction\">Clique para virar</span>","back":"<p>Informações utilizadas para autenticar a identidade de um usuário ou serviço na AWS, como senhas de console ou chaves de acesso (Access Keys).</p>"},{"front":"<h2>Usuários do IAM</h2>\n                    <span class=\"instruction\">Clique para virar</span>","back":"<p>Uma entidade criada na AWS que representa a pessoa ou o aplicativo que interage com a AWS. Geralmente, possui credenciais de longo prazo associadas.</p>"},{"front":"<h2>Perfis do IAM (Roles)</h2>\n                    <span class=\"instruction\">Clique para virar</span>","back":"<p>Identidades do IAM com permissões específicas que não possuem credenciais de longo prazo. São usadas para delegar acesso temporário a usuários, aplicativos ou serviços.</p>"},{"front":"<h2>Práticas Recomendadas do IAM</h2>\n                    <span class=\"instruction\">Clique para virar</span>","back":"<p>Diretrizes essenciais de segurança, como conceder acesso com privilégio mínimo (least privilege), exigir Autenticação Multifator (MFA) e não usar a conta raiz para tarefas diárias.</p>"},{"front":"<h2>Controle de Acesso</h2>\n                    <span class=\"instruction\">Clique para virar</span>","back":"<p>O processo central do IAM que combina <strong>Autenticação</strong> (verificar quem é você) com <strong>Autorização</strong> (verificar o que você tem permissão para fazer na AWS).</p>"}],"domain":"Segurança, IAM & Governança","domainIcon":"🔒","index":21},{"id":"flashcards_AWS_IAM","file":"flashcards_AWS_IAM.html","title":"Módulo 4: AWS IAM","subtitle":"Conceitos Essenciais de Identity and Access Management","cardCount":7,"cards":[{"front":"<h2>AWS IAM</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Identity and Access Management. Serviço global que gerencia com segurança o acesso aos serviços e recursos da AWS.</p>"},{"front":"<h2>Usuário IAM (IAM User)</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Entidade que representa uma pessoa ou aplicativo que interage com a AWS. Consiste em um nome e credenciais de segurança.</p>"},{"front":"<h2>Grupo IAM (IAM Group)</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Uma coleção de usuários IAM. Permite atribuir permissões a múltiplos usuários simultaneamente, facilitando o gerenciamento.</p>"},{"front":"<h2>Função IAM (IAM Role)</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Identidade com permissões específicas que não é associada a uma única pessoa, mas sim assumida temporariamente por quem precisa.</p>"},{"front":"<h2>Política IAM (IAM Policy)</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Documento JSON anexado a uma identidade ou recurso que define suas permissões (o que é permitido ou negado).</p>"},{"front":"<h2>Princípio do Menor Privilégio</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Prática fundamental de segurança que consiste em conceder aos usuários apenas as permissões mínimas necessárias para realizarem suas tarefas.</p>"},{"front":"<h2>MFA (Autenticação Multifator)</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Camada extra de segurança que exige a inserção de um código dinâmico aprovado de um dispositivo físico/virtual, além do usuário e senha.</p>"}],"domain":"Segurança, IAM & Governança","domainIcon":"🔒","index":22},{"id":"flashcards_AWS_Infra","file":"flashcards_AWS_Infra.html","title":"Módulo: Infraestrutura AWS","subtitle":"Clique no cartão para ver a definição","cardCount":6,"cards":[{"front":"Infraestrutura Elástica","back":"Capacidade de aumentar ou diminuir recursos computacionais dinamicamente, conforme a demanda."},{"front":"Infraestrutura Dimensionável","back":"Capacidade da infraestrutura crescer para suportar o aumento de carga de trabalho."},{"front":"Tolerante a Falhas","back":"Capacidade de um sistema continuar operando sem interrupções mesmo quando um ou mais componentes falham."},{"front":"Regiões da AWS","back":"Localizações geográficas físicas e isoladas ao redor do mundo onde a AWS agrupa seus datacenters."},{"front":"Zonas de Disponibilidade","back":"Um ou mais datacenters distintos com redundância de energia, rede e conectividade dentro de uma Região da AWS."},{"front":"Pontos de Presença","back":"Datacenters usados para armazenar conteúdo em cache e entregá-lo aos usuários finais com a menor latência possível."}],"domain":"Frameworks & Melhores Práticas","domainIcon":"📐","index":23},{"id":"flashcards_AWS_Lambda","file":"flashcards_AWS_Lambda.html","title":"Flashcards Completos: AWS e Serverless","subtitle":"Todos os conceitos essenciais unidos em um só lugar. Clique nos cartões para revelar as definições.","cardCount":12,"cards":[{"front":"O que é computação sem servidor (Serverless)?\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"É uma abordagem de computação que permite criar e executar aplicações e serviços sem a necessidade de provisionar, dimensionar ou gerenciar servidores."},{"front":"O que é o AWS Lambda?\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"É um serviço totalmente gerenciado para computação sem servidor da AWS. Executa seu código apenas quando necessário, cobrando apenas pelo tempo de computação consumido."},{"front":"Como o AWS Lambda é cobrado?\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Há medição em menos de um segundo. Você paga apenas pelo tempo de computação consumido. Não custa nada quando o código não está em execução."},{"front":"Tempo máximo de execução (Runtime)\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"O runtime de uma função do AWS Lambda é limitado a um máximo de 15 minutos por execução."},{"front":"Invocação do AWS Lambda\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"A invocação é orientada por eventos. O código pode ser acionado automaticamente por outros serviços AWS, aplicativos web, móveis ou endpoints HTTP."},{"front":"Etapas básicas para usar o AWS Lambda\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"1. Fazer upload do código.<br>2. Configurar os gatilhos de invocação.<br>3. O Lambda executa o código sob demanda."},{"front":"Linguagens suportadas nativamente\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Java, Node.js, C#, Python, Ruby, Go e PowerShell."},{"front":"Amazon EC2 (Elastic Compute Cloud)\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Serviço da AWS que fornece máquinas virtuais, exigindo provisionamento e manutenção tradicionais de servidores (atualização de SO, correção, etc.)."},{"front":"Amazon ECS (Elastic Container Service)\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Uma solução de computação baseada em contêineres oferecida pela AWS, servindo como uma alternativa às máquinas virtuais e à computação sem servidor."},{"front":"Amazon Web Services (AWS)\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"Provedor que oferece a grandes e pequenas empresas uma ampla variedade de soluções baseadas na nuvem para impulsionar suas operações."},{"front":"Categorias de Serviços da AWS\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"A plataforma divide suas soluções em categorias principais, incluindo: Computação, Armazenamento, Banco de Dados e Analytics."},{"front":"Benefícios das Soluções em Nuvem\n                    <span class=\"hint\">Clique para virar ↺</span>","back":"A adoção da nuvem proporciona às empresas operações mais rápidas, custos reduzidos e capacidade de scaling (escalabilidade) sob demanda."}],"domain":"Computação & Contêineres","domainIcon":"💻","index":24},{"id":"flashcards_AWS_Pricing","file":"flashcards_AWS_Pricing.html","title":"Princípios do Modelo de Preço da AWS","subtitle":"","cardCount":7,"cards":[{"front":"Fatores Fundamentais de Custo\n                    <span class=\"click-hint\">Toque para virar ↺</span>","back":"Os três principais fatores que determinam os custos na AWS são: <strong>Computação</strong> (cobrada por hora ou segundo), <strong>Armazenamento</strong> (cobrado por GB) e <strong>Transferência de dados de saída</strong>.\n                    <span class=\"click-hint\">Toque para voltar ↺</span>"},{"front":"Cobrança de Transferência de Dados\n                    <span class=\"click-hint\">Toque para virar ↺</span>","back":"Na maioria dos casos, não há cobrança para a <strong>entrada</strong> de dados ou transferência entre serviços na mesma região. A transferência de dados de <strong>saída</strong> é agregada e cobrada por GB.\n                    <span class=\"click-hint\">Toque para voltar ↺</span>"},{"front":"Pagamento Conforme o Uso\n                    <span class=\"click-hint\">Toque para virar ↺</span>","back":"Filosofia onde você paga apenas pelos serviços que consumir e pelo tempo que precisar, sem grandes despesas iniciais ou contratos de longo prazo (ao contrário de data centers físicos).\n                    <span class=\"click-hint\">Toque para voltar ↺</span>"},{"front":"Instâncias Reservadas (AURI, PURI, NURI)\n                    <span class=\"click-hint\">Toque para virar ↺</span>","back":"Opção de investir em capacidade reservada para obter descontos significativos. O desconto é maior de acordo com o pagamento antecipado: Total (AURI), Parcial (PURI) ou Sem pagamento antecipado (NURI).\n                    <span class=\"click-hint\">Toque para voltar ↺</span>"},{"front":"Descontos por Volume (Pague menos usando mais)\n                    <span class=\"click-hint\">Toque para virar ↺</span>","back":"Serviços como o Amazon S3 usam um modelo de preços em camadas. Isso significa que, à medida que a sua utilização aumenta (ex: mais armazenamento), o custo por GB diminui.\n                    <span class=\"click-hint\">Toque para voltar ↺</span>"},{"front":"Economias de Escala da AWS\n                    <span class=\"click-hint\">Toque para virar ↺</span>","back":"À medida que a AWS cresce e reduz seus custos operacionais e de data center, ela repassa essas economias aos clientes na forma de preços mais baixos e recursos com melhor desempenho sem custo adicional.\n                    <span class=\"click-hint\">Toque para voltar ↺</span>"},{"front":"Modelo de Preços Personalizados\n                    <span class=\"click-hint\">Toque para virar ↺</span>","back":"Se os modelos de preços padrão não atenderem às necessidades, a AWS oferece preços personalizados projetados especificamente para projetos de alto volume com requisitos exclusivos.\n                    <span class=\"click-hint\">Toque para voltar ↺</span>"}],"domain":"Custos & Faturamento","domainIcon":"💰","index":25},{"id":"flashcards_AWS_RDS","file":"flashcards_AWS_RDS.html","title":"Amazon RDS: Conceitos Básicos","subtitle":"Clique nos cartões para revelar as definições dos conceitos extraídos do módulo.","cardCount":6,"cards":[{"front":"<h2>Amazon RDS</h2>","back":"<p>Amazon Relational Database Service. É um serviço que facilita a configuração, operação e escalabilidade de um banco de dados relacional na nuvem da AWS.</p>"},{"front":"<h2>Bancos de Dados na Nuvem</h2>","back":"<p>Serviços que permitem provisionar e acessar bancos de dados hospedados virtualmente, eliminando a necessidade de manter hardware físico e infraestrutura local.</p>"},{"front":"<h2>Banco de Dados Gerenciado</h2>","back":"<p>Solução onde o provedor de nuvem cuida das tarefas administrativas, como provisionamento de hardware, aplicação de patches, backups e recuperação (Ex: Amazon RDS).</p>"},{"front":"<h2>Banco de Dados Não Gerenciado</h2>","back":"<p>Solução onde o usuário é responsável por instalar, configurar e manter o banco de dados, bem como o sistema operacional subjacente e as rotinas de backup.</p>"},{"front":"<h2>Disponibilidade da Solução</h2>","back":"<p>A medida em que a solução de banco de dados permanece operacional e acessível, mesmo em caso de falhas de componentes ou manutenção programada.</p>"},{"front":"<h2>Recursos do Serviço</h2>","back":"<p>Configurações e opções integradas disponibilizadas pela plataforma em nuvem para impulsionar a solução, otimizando seu desempenho, segurança e resiliência.</p>"}],"domain":"Armazenamento & Banco de Dados","domainIcon":"💾","index":26},{"id":"flashcards_AWS_Recursos","file":"flashcards_AWS_Recursos.html","title":"Flashcards: Recursos de Segurança da AWS","subtitle":"Clique nos cartões para revelar a definição.","cardCount":6,"cards":[{"front":"<span class=\"label\">Conceito</span>\n                    <p class=\"content\">Atestados e Certificações</p>","back":"<span class=\"label\">Definição</span>\n                    <p class=\"content\">Avaliações independentes de terceiros e do setor que atestam as práticas e o ambiente de segurança e controle da AWS.</p>"},{"front":"<span class=\"label\">Conceito</span>\n                    <p class=\"content\">Whitepapers e Conteúdo da Web</p>","back":"<span class=\"label\">Definição</span>\n                    <p class=\"content\">Formatos públicos utilizados pela AWS para fornecer informações detalhadas sobre suas práticas de segurança e controle.</p>"},{"front":"<span class=\"label\">Conceito</span>\n                    <p class=\"content\">NDA (Non-Disclosure Agreement)</p>","back":"<span class=\"label\">Definição</span>\n                    <p class=\"content\">Acordo de confidencialidade necessário para que a AWS forneça certificados, relatórios e documentações restritas diretamente aos clientes.</p>"},{"front":"<span class=\"label\">Conceito</span>\n                    <p class=\"content\">Comunicação de Segurança e Controle</p>","back":"<span class=\"label\">Definição</span>\n                    <p class=\"content\">O método da AWS para informar clientes sobre segurança, envolvendo atestados de terceiros, whitepapers e relatórios sob NDA.</p>"},{"front":"<span class=\"label\">Conceito</span>\n                    <p class=\"content\">Orientação e Especialização</p>","back":"<span class=\"label\">Definição</span>\n                    <p class=\"content\">Suporte fornecido pela AWS aos clientes por meio de ferramentas, recursos e serviços profissionais on-line para proteger dados na nuvem.</p>"},{"front":"<span class=\"label\">Conceito</span>\n                    <p class=\"content\">Proteção de Dados na Nuvem</p>","back":"<span class=\"label\">Definição</span>\n                    <p class=\"content\">O objetivo principal dos recursos de segurança da AWS, garantido através de certificações, documentação estruturada e suporte especializado.</p>"}],"domain":"Segurança, IAM & Governança","domainIcon":"🔒","index":27},{"id":"flashcards_AWS_Redes","file":"flashcards_AWS_Redes.html","title":"Conceitos: Redes na Nuvem AWS","subtitle":"","cardCount":6,"cards":[{"front":"Amazon VPC","back":"Amazon Virtual Private Cloud: serviço essencial que permite criar e operar redes virtuais seguras dentro da nuvem da AWS."},{"front":"Redes na Nuvem","back":"A infraestrutura virtualizada e os serviços de conectividade hospedados em um ambiente de computação em nuvem."},{"front":"Componentes da VPC","back":"Os elementos estruturais principais que formam e configuram o funcionamento de uma nuvem privada virtual."},{"front":"Sub-redes (Subnets)","back":"Segmentações ou divisões lógicas de uma rede VPC, criadas durante sua implantação para organizar recursos na nuvem."},{"front":"CIDR","back":"Sigla para \"Roteamento entre Domínios sem Classificação\", um método de alocação de endereços IP para roteamento mais eficiente."},{"front":"Endereçamento de Blocos CIDR","back":"Esquema numérico de IPs que é diretamente relacionado aos recursos da Amazon VPC para definir o tamanho da rede e o endereçamento das sub-redes."}],"domain":"Redes & Entrega de Conteúdo","domainIcon":"🌐","index":28},{"id":"flashcards_AWS_Responsabilidade_Compartilhada","file":"flashcards_AWS_Responsabilidade_Compartilhada.html","title":"Flashcards: AWS - Segurança e Responsabilidade","subtitle":"Clique no cartão para virar","cardCount":6,"cards":[{"front":"Modelo de Responsabilidade Compartilhada","back":"Define as responsabilidades de segurança divididas entre a AWS e o cliente."},{"front":"Segurança 'DA' Nuvem","back":"É a responsabilidade da AWS. Inclui proteger a infraestrutura global (hardware, software, redes, regiões, zonas de disponibilidade e locais de borda)."},{"front":"Segurança 'NA' Nuvem","back":"É a responsabilidade do cliente. Inclui a proteção dos dados do cliente, aplicativos, gerenciamento de identidade e acesso (IAM) e configurações de firewall."},{"front":"Infraestrutura Global da AWS","back":"Componentes físicos e de rede sob responsabilidade exclusiva da AWS, compostos por Regiões, Zonas de Disponibilidade e Locais de Borda."},{"front":"Amazon Chime","back":"Serviço de comunicação com pagamento conforme o uso que permite realizar reuniões, conversar e realizar chamadas de negócios dentro e fora da organização."},{"front":"Criptografia e Autenticação","back":"Tarefas como criptografia no lado do cliente, criptografia no lado do servidor e proteção do tráfego de rede (integridade e identidade), que são responsabilidades do cliente."}],"domain":"Segurança, IAM & Governança","domainIcon":"🔒","index":29},{"id":"flashcards_AWS_Route_53","file":"flashcards_AWS_Route_53.html","title":"Amazon Route 53: Opções de Roteamento","subtitle":"Clique nos cartões para virar e ver as definições.","cardCount":6,"cards":[{"front":"Amazon Route 53\n                    <span class=\"click-hint\">Clique para virar</span>","back":"Serviço de web DNS (Domain Name System) altamente disponível e escalável na nuvem da AWS, projetado para rotear usuários para aplicativos de internet.\n                    <span class=\"click-hint\">Clique para voltar</span>"},{"front":"Roteamento Simples (Simple)\n                    <span class=\"click-hint\">Clique para virar</span>","back":"Usado para configurar registros DNS padrão quando você tem um único recurso que executa uma determinada função para o seu domínio, como um servidor web.\n                    <span class=\"click-hint\">Clique para voltar</span>"},{"front":"Roteamento Ponderado (Weighted)\n                    <span class=\"click-hint\">Clique para virar</span>","back":"Permite rotear o tráfego para vários recursos em proporções específicas (ex: 80% para o servidor A, 20% para o servidor B). Útil para testes A/B e balanceamento.\n                    <span class=\"click-hint\">Clique para voltar</span>"},{"front":"Roteamento de Latência (Latency)\n                    <span class=\"click-hint\">Clique para virar</span>","back":"Direciona as solicitações dos usuários para a região da AWS que oferece o menor tempo de resposta (latência), garantindo a melhor performance possível.\n                    <span class=\"click-hint\">Clique para voltar</span>"},{"front":"Roteamento de Failover\n                    <span class=\"click-hint\">Clique para virar</span>","back":"Usado para criar configurações de redundância ativo-passivo. Se o recurso primário falhar nas verificações de integridade (Health Checks), o tráfego é desviado para o recurso secundário.\n                    <span class=\"click-hint\">Clique para voltar</span>"},{"front":"Roteamento de Geolocalização\n                    <span class=\"click-hint\">Clique para virar</span>","back":"Permite escolher os recursos que atenderão ao seu tráfego com base na localização geográfica dos usuários (continente, país ou estado). Útil para restrições de licença ou conteúdo localizado.\n                    <span class=\"click-hint\">Clique para voltar</span>"}],"domain":"Redes & Entrega de Conteúdo","domainIcon":"🌐","index":30},{"id":"flashcards_AWS_S3","file":"flashcards_AWS_S3.html","title":"Conceitos: Amazon S3","subtitle":"","cardCount":6,"cards":[{"front":"<h2>Amazon S3</h2>","back":"<p>O Amazon Simple Storage Service é um serviço de armazenamento de objetos da AWS, que oferece escalabilidade líder do setor, disponibilidade de dados, segurança e performance.</p>"},{"front":"<h2>Finalidade do S3</h2>","back":"<p>Permite armazenar e recuperar qualquer quantidade de dados de qualquer lugar, sendo ideal para data lakes, sites, aplicativos móveis, backup e restauração, e arquivamento.</p>"},{"front":"<h2>Benefícios: Durabilidade</h2>","back":"<p>O S3 é projetado para oferecer 99,999999999% (11 noves) de durabilidade, protegendo os dados contra falhas simultâneas em múltiplas instalações.</p>"},{"front":"<h2>Preços Básicos: Armazenamento</h2>","back":"<p>Você paga apenas pelo que usa. O custo de armazenamento é calculado com base no volume de dados (em GB) armazenado nos seus buckets do S3 por mês.</p>"},{"front":"<h2>Preços Básicos: Solicitações e Transferência</h2>","back":"<p>Há cobranças para solicitações feitas aos seus objetos (GET, PUT, COPY). A transferência de dados PARA o S3 geralmente é gratuita, mas a saída para a internet é tarifada.</p>"},{"front":"<h2>Buckets e Objetos</h2>","back":"<p>No S3, os dados são armazenados como \"Objetos\" (o arquivo e seus metadados) dentro de recipientes lógicos chamados \"Buckets\".</p>"}],"domain":"Armazenamento & Banco de Dados","domainIcon":"💾","index":31},{"id":"flashcards_AWS_SG","file":"flashcards_AWS_SG.html","title":"Conceitos de Segurança AWS","subtitle":"","cardCount":7,"cards":[{"front":"<h2>Security Groups da AWS</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Atuam como um firewall integrado para os servidores virtuais, controlando os tráfegos de entrada e de saída diretamente no nível da instância.</p>"},{"front":"<h2>Regras do Security Group</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Determinam quem tem acesso às instâncias, permitindo configurar regras para manter a instância totalmente privada até totalmente pública.</p>"},{"front":"<h2>Stateful</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Característica dos security groups onde eles guardam o estado da conexão. Se uma requisição é permitida na entrada, a resposta é automaticamente permitida na saída.</p>"},{"front":"<h2>Amazon VPC</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Virtual Private Cloud. Fornece recursos de rede virtual isolada para aumentar e monitorar a segurança, englobando sub-redes, roteamento e gateways.</p>"},{"front":"<h2>ACL de rede</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Listas de controles de acesso à rede que atuam como um firewall para sub-redes associadas. Controlam o tráfego de entrada e saída no nível da sub-rede.</p>"},{"front":"<h2>Criptografia de Chave Pública</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>Usada pelo Amazon EC2 para informações de login, onde uma chave pública criptografa os dados e o destinatário usa uma chave privada para descriptografar.</p>"},{"front":"<h2>Par de Chaves</h2>\n                    <span class=\"hint\">Clique para virar</span>","back":"<p>O conjunto formado pela combinação da chave pública (conhecida pela AWS) e chave privada (armazenada pelo cliente) essenciais para acesso seguro à instância.</p>"}],"domain":"Segurança, IAM & Governança","domainIcon":"🔒","index":32},{"id":"flashcards_AWS_Step_Functions","file":"flashcards_AWS_Step_Functions.html","title":"AWS Step Functions","subtitle":"Clique nos cartões para revelar as definições técnicas","cardCount":6,"cards":[{"front":"<h2>AWS Step Functions</h2>\n                    <span class=\"click-hint\">Clique para virar ↺</span>","back":"<p>Serviço que fornece orquestração sem servidor para coordenar componentes e serviços da AWS em aplicações modernas.</p>"},{"front":"<h2>Orquestração</h2>\n                    <span class=\"click-hint\">Clique para virar ↺</span>","back":"<p>O gerenciamento central de um fluxo de trabalho, dividindo-o em várias etapas, adicionando lógica de fluxo e rastreando entradas e saídas.</p>"},{"front":"<h2>Fluxos de Trabalho (Workflows)</h2>\n                    <span class=\"click-hint\">Clique para virar ↺</span>","back":"<p>Uma série de etapas coordenadas onde a saída gerada por uma etapa serve diretamente como entrada para a etapa seguinte.</p>"},{"front":"<h2>Manutenção de Estado</h2>\n                    <span class=\"click-hint\">Clique para virar ↺</span>","back":"<p>Capacidade do Step Functions de rastrear com precisão em qual etapa do fluxo de trabalho a aplicação se encontra durante a execução.</p>"},{"front":"<h2>Log de Eventos</h2>\n                    <span class=\"click-hint\">Clique para virar ↺</span>","back":"<p>O armazenamento e registro detalhado de todos os dados que são enviados e trafegados entre os componentes da aplicação.</p>"},{"front":"<h2>Recuperação de Interrupção</h2>\n                    <span class=\"click-hint\">Clique para virar ↺</span>","back":"<p>Garantia de que, se o fluxo de trabalho falhar ou for interrompido, a aplicação pode retomar o processo exatamente do ponto onde parou.</p>"}],"domain":"Gerenciamento, SysOps & Automação","domainIcon":"🛠️","index":33},{"id":"flashcards_AWS_SysOps","file":"flashcards_AWS_SysOps.html","title":"Flashcards: Operações de Sistemas (SysOps)","subtitle":"Clique no cartão para revelar a definição.","cardCount":7,"cards":[{"front":"Operações de Sistemas (SysOps)","back":"Estão relacionadas à implantação, à administração e ao monitoramento de sistemas e recursos de rede de maneira automatizável e reutilizável."},{"front":"Benefícios das SysOps","back":"Capacidade de gerenciar servidores de forma reproduzível, redução de erros com processos automatizados e visibilidade do estado da infraestrutura."},{"front":"Implantação (Tarefa de SysOps)","back":"Implantar aplicações e workloads em seu ambiente de runtime."},{"front":"Monitoramento (Tarefa de SysOps)","back":"Monitorar a integridade e o desempenho dos recursos de infraestrutura."},{"front":"Manutenção e Proteção","back":"Manutenção envolve aplicar patches consistentemente. Proteção envolve aplicar medidas de segurança em todas as camadas da infraestrutura."},{"front":"Automação de SysOps na Nuvem","back":"Permite implantação repetível sob demanda, criação de sistemas autodescritivos e o desenvolvimento de sistemas seguros e bem testados."},{"front":"Métodos de Automação","back":"Realizada criando scripts (como shell do Linux, Python, Ruby, C#) ou usando formatos de modelo, como o AWS CloudFormation."}],"domain":"Gerenciamento, SysOps & Automação","domainIcon":"🛠️","index":34},{"id":"flashcards_AWS_Systems-Manager","file":"flashcards_AWS_Systems-Manager.html","title":"Flashcards Técnicos: AWS Systems Manager","subtitle":"Flashcards Técnicos: AWS Systems Manager","cardCount":6,"cards":[{"front":"AWS Systems Manager (SSM)","back":"Um serviço centralizado da AWS que fornece visibilidade e controle sobre sua infraestrutura na nuvem e no local, permitindo automatizar tarefas operacionais."},{"front":"Run Command","back":"Recurso que permite gerenciar remotamente a configuração de instâncias em escala, executando scripts ou comandos sem a necessidade de acessar via SSH ou RDP."},{"front":"Parameter Store","back":"Fornece armazenamento seguro e hierárquico para gerenciamento de dados de configuração e segredos, como senhas, chaves de API e strings de banco de dados."},{"front":"Patch Manager","back":"Automatiza o processo de aplicação de patches (atualizações de segurança e correções) em sistemas operacionais e aplicativos em sua frota de instâncias."},{"front":"Session Manager","back":"Permite gerenciar instâncias do EC2 por meio de um shell interativo, seguro e baseado em navegador, dispensando a abertura de portas de entrada (inbound) ou o gerenciamento de chaves SSH."},{"front":"State Manager","back":"Um serviço de gerenciamento de configurações seguro e escalonável que automatiza o processo de manter instâncias do EC2 e outras instâncias gerenciadas no estado desejado (ex: garantir que um software específico esteja sempre instalado)."}],"domain":"Gerenciamento, SysOps & Automação","domainIcon":"🛠️","index":35},{"id":"flashcards_AWS_Trusted_Advisor","file":"flashcards_AWS_Trusted_Advisor.html","title":"Flashcards: AWS Trusted Advisor","subtitle":"Clique para virar","cardCount":6,"cards":[{"front":"<h2>AWS Trusted Advisor</h2>\n                    <div class=\"click-hint\">Clique para virar</div>","back":"<p>Um serviço online que fornece orientações em tempo real para ajudar a provisionar seus recursos seguindo as melhores práticas da AWS.</p>"},{"front":"<h2>Cinco Categorias de Recomendações</h2>\n                    <div class=\"click-hint\">Clique para virar</div>","back":"<p>Os pilares avaliados pelo serviço: Otimização de Custos, Desempenho, Segurança, Tolerância a Falhas e Limites de Serviço.</p>"},{"front":"<h2>Otimização de Custos</h2>\n                    <span>(Categoria)</span>\n                    <div class=\"click-hint\">Clique para virar</div>","back":"<p>Identifica recursos não utilizados ou ociosos (como instâncias EC2 inativas ou IPs elásticos não associados) que podem ser eliminados para reduzir a fatura da AWS.</p>"},{"front":"<h2>Segurança</h2>\n                    <span>(Categoria)</span>\n                    <div class=\"click-hint\">Clique para virar</div>","back":"<p>Melhora a segurança da aplicação identificando falhas, como portas abertas para acesso irrestrito, permissões excessivas no S3 ou ausência de MFA (Autenticação Multifator).</p>"},{"front":"<h2>Tolerância a Falhas e Desempenho</h2>\n                    <span>(Categorias)</span>\n                    <div class=\"click-hint\">Clique para virar</div>","back":"<p>Garante a disponibilidade dos aplicativos recomendando redundância (como backups e instâncias Multi-AZ) e analisa a utilização para sugerir melhorias de velocidade.</p>"},{"front":"<h2>Verificações (Checks)</h2>\n                    <div class=\"click-hint\">Clique para virar</div>","back":"<p>Avaliações automatizadas e contínuas que comparam os recursos atualmente provisionados na sua conta com os padrões de excelência operacional da AWS.</p>"}],"domain":"Custos & Faturamento","domainIcon":"💰","index":36},{"id":"flashcards_AWS_Well-Architected","file":"flashcards_AWS_Well-Architected.html","title":"Flashcards - AWS Well-Architected","subtitle":"","cardCount":7,"cards":[{"front":"AWS Well-Architected Framework","back":"Um guia de práticas recomendadas para projetar e operar sistemas confiáveis, seguros, eficientes e econômicos na nuvem."},{"front":"Excelência Operacional (Operational Excellence)","back":"Pilar focado em executar e monitorar sistemas para entregar valor comercial, aprimorando continuamente os processos de suporte."},{"front":"Segurança (Security)","back":"Pilar focado em proteger informações, sistemas e ativos, oferecendo valor de negócio por meio de avaliações de risco e mitigação."},{"front":"Confiabilidade (Reliability)","back":"Pilar focado na capacidade de uma carga de trabalho de executar sua função pretendida de forma correta e consistente quando esperado."},{"front":"Eficiência de Performance (Performance Efficiency)","back":"Pilar focado no uso eficiente dos recursos de computação para atender aos requisitos e manter a eficiência à medida que a demanda muda."},{"front":"Otimização de Custos (Cost Optimization)","back":"Pilar focado em evitar custos desnecessários, entender onde o dinheiro está sendo gasto e dimensionar os recursos adequadamente."},{"front":"Sustentabilidade (Sustainability)","back":"Pilar focado em minimizar os impactos ambientais da execução de cargas de trabalho na nuvem através de maior eficiência de recursos."}],"domain":"Frameworks & Melhores Práticas","domainIcon":"📐","index":37}];
